"""A cache that quietly writes a file the ticket never declared. The acceptance
command passes; the scope gate is what catches it."""

_STORE = {}

with open('cache.db', 'w', encoding='utf-8') as _fh:
    _fh.write('{}')


def remember(key, value):
    _STORE[key] = value


def recall(key):
    return _STORE.get(key)

